+function makeTree(id = TREE_ID): Workspace {
+  return { id, name: "Saved View Workspace", role: "owner" };
+}
+
+function makeView(overrides: Partial<SavedViewDB> = {}): SavedViewDB {
+  return {
+    id: "v1",
+    workspace_id: TREE_ID,
+    owner_id: "u1",
+    name: "My view",
+    focus_member_id: "m1",
+    section_ids: ["s1"],
+    ancestor_depth: 3,
+    descendant_depth: 3,
+    include_partners: true,
+    filters: {},
+    config_version: 1,
+    version: 1,
+    created_at: "2024-01-01T00:00:00Z",
+    updated_at: "2024-01-01T00:00:00Z",
+    last_opened: null,
+    positions: [],
+    ...overrides,
+  };
+}
+
+beforeEach(() => {
+  vi.clearAllMocks();
+  useSavedViewStore.setState({ views: [], initialized: false, loading: false });
+  useWorkspaceStore.setState({ selectedTree: undefined });
+});
+
+describe("useSavedViewStore — refreshSavedViews", () => {
+  it("clears views when no tree is selected", async () => {
+    useSavedViewStore.setState({ views: [makeView()], initialized: true });
+
+    await useSavedViewStore.getState().refreshSavedViews();
+
+    expect(useSavedViewStore.getState().views).toHaveLength(0);
+    expect(WorkspaceService.getSavedViews).not.toHaveBeenCalled();
+  });
+
+  it("fetches views from the service", async () => {
+    useWorkspaceStore.setState({ selectedTree: makeTree() });
+    vi.mocked(WorkspaceService.getSavedViews).mockResolvedValue([makeView()]);
+
+    await useSavedViewStore.getState().refreshSavedViews();
+
+    expect(WorkspaceService.getSavedViews).toHaveBeenCalledWith(TREE_ID);
+    expect(useSavedViewStore.getState().views).toHaveLength(1);
+    expect(useSavedViewStore.getState().initialized).toBe(true);
+  });
+});
+
+describe("useSavedViewStore — createSavedView", () => {
+  it("creates a view then refreshes the list", async () => {
+    useWorkspaceStore.setState({ selectedTree: makeTree() });
+    vi.mocked(WorkspaceService.createSavedView).mockResolvedValue(makeView());
+    vi.mocked(WorkspaceService.getSavedViews).mockResolvedValue([makeView()]);
+
+    await useSavedViewStore.getState().createSavedView({ name: "My view" });
+
+    expect(WorkspaceService.createSavedView).toHaveBeenCalledWith(TREE_ID, {
+      name: "My view",
+    });
+    expect(WorkspaceService.getSavedViews).toHaveBeenCalled();
+  });
+
+  it("throws when no tree is selected", async () => {
+    await expect(
+      useSavedViewStore.getState().createSavedView({ name: "Orphan" }),
+    ).rejects.toThrow();
+    expect(WorkspaceService.createSavedView).not.toHaveBeenCalled();
+  });
+});
+
+describe("useSavedViewStore — updateSavedView", () => {
+  it("updates a view then refreshes the list", async () => {
+    useWorkspaceStore.setState({ selectedTree: makeTree() });
+    const updated = makeView({ name: "Renamed", version: 2 });
+    vi.mocked(WorkspaceService.updateSavedView).mockResolvedValue(updated);
+    vi.mocked(WorkspaceService.getSavedViews).mockResolvedValue([updated]);
+
+    const result = await useSavedViewStore
+      .getState()
+      .updateSavedView("v1", { name: "Renamed", expected_version: 1 });
+
+    expect(WorkspaceService.updateSavedView).toHaveBeenCalledWith(
+      TREE_ID,
+      "v1",
+      { name: "Renamed", expected_version: 1 },
+    );
+    expect(result.name).toBe("Renamed");
+    expect(WorkspaceService.getSavedViews).toHaveBeenCalled();
+  });
+
+  it("propagates a stale-conflict rejection without refreshing", async () => {
+    useWorkspaceStore.setState({ selectedTree: makeTree() });
+    const conflict = Object.assign(new Error("stale"), { status: 409 });
+    vi.mocked(WorkspaceService.updateSavedView).mockRejectedValue(conflict);
+
+    await expect(
+      useSavedViewStore
+        .getState()
+        .updateSavedView("v1", { name: "Renamed", expected_version: 1 }),
+    ).rejects.toBe(conflict);
+    expect(WorkspaceService.getSavedViews).not.toHaveBeenCalled();
+  });
+});
+
+describe("useSavedViewStore — deleteSavedView", () => {
+  it("deletes a view then refreshes the list", async () => {
+    useWorkspaceStore.setState({ selectedTree: makeTree() });
+    vi.mocked(WorkspaceService.deleteSavedView).mockResolvedValue(undefined);
+    vi.mocked(WorkspaceService.getSavedViews).mockResolvedValue([]);
+
+    await useSavedViewStore.getState().deleteSavedView("v1");
+
+    expect(WorkspaceService.deleteSavedView).toHaveBeenCalledWith(
+      TREE_ID,
+      "v1",
+    );
+    expect(WorkspaceService.getSavedViews).toHaveBeenCalled();
+  });
+});
+
+describe("useSavedViewStore — duplicateSavedView", () => {
+  it("creates a new view carrying over the source's configuration", async () => {
+    useWorkspaceStore.setState({ selectedTree: makeTree() });
+    const source = makeView();
+    vi.mocked(WorkspaceService.createSavedView).mockResolvedValue(
+      makeView({ id: "v2", name: "My view (copy)" }),
+    );
+    vi.mocked(WorkspaceService.getSavedViews).mockResolvedValue([]);
+
+    await useSavedViewStore
+      .getState()
+      .duplicateSavedView(source, "My view (copy)");
+
+    expect(WorkspaceService.createSavedView).toHaveBeenCalledWith(TREE_ID, {
+      name: "My view (copy)",
+      focus_member_id: source.focus_member_id,
+      section_ids: source.section_ids,
+      ancestor_depth: source.ancestor_depth,
+      descendant_depth: source.descendant_depth,
+      include_partners: source.include_partners,
+    });
+  });
+});
+
+describe("useSavedViewStore — clear", () => {
+  it("empties the views slice", () => {
+    useSavedViewStore.setState({ views: [makeView()], initialized: true });
+
+    useSavedViewStore.getState().clear();
+
+    expect(useSavedViewStore.getState().views).toHaveLength(0);
+    expect(useSavedViewStore.getState().initialized).toBe(false);
+  });
+});

import { create } from "zustand";
import {
  SectionCreateInput,
  SectionDB,
  SectionDependentsDB,
  SectionPreviewDB,
  SectionSuggestionDB,
  SectionUpdateInput,
} from "@/types/section";
import { MemberDB } from "@/types/member";
import { WorkspaceService } from "@/services/WorkspaceService";
import { activeTreeId, isActiveTree } from "@/hooks/useWorkspaceStore";

interface SectionState {
  sections: SectionDB[];
  initialized: boolean;
  loading: boolean;
  refreshSections: (workspaceId?: string) => Promise<void>;
  previewSection: (
    rootMemberId: string,
    direction: "direct_family" | "partnership",
  ) => Promise<SectionPreviewDB>;
  createSection: (payload: SectionCreateInput) => Promise<SectionDB>;
  updateSection: (
    sectionId: string,
    payload: SectionUpdateInput,
  ) => Promise<void>;
  getSectionDependents: (sectionId: string) => Promise<SectionDependentsDB>;
  deleteSection: (sectionId: string, reassignScopeTo?: string) => Promise<void>;
  getSectionMembers: (sectionId: string) => Promise<MemberDB[]>;
  setSectionMembers: (sectionId: string, memberIds: string[]) => Promise<void>;
  getSectionSuggestions: (memberId: string) => Promise<SectionSuggestionDB[]>;
  /** Adds a newly-created member to each of the given sections without
   *  disturbing anyone else already in them — the confirmation step for a
   *  new-member section suggestion (#990). ``PUT .../members`` is a full
   *  replace, so this reads each section's current membership first. */
  addMemberToSections: (
    memberId: string,
    sectionIds: string[],
  ) => Promise<void>;
  clear: () => void;
}

export const useSectionStore = create<SectionState>((set, get) => {
  // Guards against a slower, superseded refresh overwriting a newer one —
  // same pattern as useActivityStore.
  let requestId = 0;

  return {
    sections: [],
    initialized: false,
    loading: false,

    refreshSections: async (workspaceId = activeTreeId()) => {
      if (!workspaceId) {
        set({ sections: [], initialized: false });
        return;
      }
      const reqId = ++requestId;
      set({ loading: true });
      try {
        const sections = await WorkspaceService.getSections(workspaceId);
        if (reqId !== requestId || !isActiveTree(workspaceId)) return;
        set({ sections, initialized: true, loading: false });
      } catch {
        if (reqId !== requestId || !isActiveTree(workspaceId)) return;
        set({ loading: false });
      }
    },

    previewSection: (rootMemberId, direction) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) throw new Error("No active tree");
      return WorkspaceService.previewSection(
        workspaceId,
        rootMemberId,
        direction,
      );
    },

    createSection: async (payload) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) throw new Error("No active tree");
      const section = await WorkspaceService.createSection(
        workspaceId,
        payload,
      );
      await get().refreshSections(workspaceId);
      return section;
    },

    updateSection: async (sectionId, payload) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) return;
      await WorkspaceService.updateSection(workspaceId, sectionId, payload);
      await get().refreshSections(workspaceId);
    },

    getSectionDependents: (sectionId) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) throw new Error("No active tree");
      return WorkspaceService.getSectionDependents(workspaceId, sectionId);
    },

    deleteSection: async (sectionId, reassignScopeTo) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) return;
      await WorkspaceService.deleteSection(
        workspaceId,
        sectionId,
        reassignScopeTo,
      );
      await get().refreshSections(workspaceId);
    },

    getSectionMembers: (sectionId) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) throw new Error("No active tree");
      return WorkspaceService.getSectionMembers(workspaceId, sectionId);
    },

    setSectionMembers: async (sectionId, memberIds) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) return;
      await WorkspaceService.setSectionMembers(
        workspaceId,
        sectionId,
        memberIds,
      );
      await get().refreshSections(workspaceId);
    },

    getSectionSuggestions: (memberId) => {
      const workspaceId = activeTreeId();
      if (!workspaceId) throw new Error("No active tree");
      return WorkspaceService.getSectionSuggestions(workspaceId, memberId);
    },

    addMemberToSections: async (memberId, sectionIds) => {
      const workspaceId = activeTreeId();
      if (!workspaceId || !sectionIds.length) return;
      await Promise.all(
        sectionIds.map(async (sectionId) => {
          const current = await WorkspaceService.getSectionMembers(
            workspaceId,
            sectionId,
